def by_price(item):
    return item[1]
items = [('a', 3), ('b', 1)]
assert sorted(items, key=by_price) == [('b', 1), ('a', 3)]
try:
    sorted(items, key=by_price(items))
    ok = False
except TypeError:
    ok = True
assert ok

def evens(limit):
    n = 0
    while n < limit:
        yield n
        n += 2
assert list(evens(7)) == [0, 2, 4, 6]

def down(start, step):
    n = start
    while n > 0:
        yield n
        n -= step
assert list(down(10, 3)) == [10, 7, 4, 1]
